/**
 * pdf-lib rewrites a document in JavaScript memory, holding both the source and
 * generated bytes plus its parsed object graph. Keep that work away from mobile
 * heaps once the source is large enough to make an OS kill plausible. Viewing
 * remains native and is intentionally not subject to this limit.
 *
 * Flattening for export/print and the page operations (reorder, merge, extract,
 * remove, rotate) both rewrite with pdf-lib, so they share one ceiling.
 */
export const MAX_MOBILE_REWRITE_BYTES = 64 * 1024 * 1024;

export function canRewriteOnMobile(
  sizeBytes: number | undefined,
  limitBytes = MAX_MOBILE_REWRITE_BYTES,
): boolean {
  return sizeBytes === undefined || (
    Number.isFinite(sizeBytes)
    && sizeBytes >= 0
    && sizeBytes <= limitBytes
  );
}

export function bytesToWholeMiB(bytes: number): number {
  return Math.floor(bytes / (1024 * 1024));
}

/**
 * The combined size of several documents a single rewrite holds at once, as a
 * merge does. Undefined means at least one size is unknown; the caller allows it
 * through for the same reason a single document with no recorded size is allowed.
 */
export function totalKnownSizeBytes(sizes: (number | undefined)[]): number | undefined {
  if (!sizes.every((size): size is number => size !== undefined)) return undefined;
  return sizes.reduce((sum, size) => sum + size, 0);
}
